import java.io.*;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;

public class SecurityMonitoringSystem {

    public enum EventType {
        LOGIN_SUCCESS, LOGIN_FAILURE, LOGOUT, ACCESS_GRANTED, ACCESS_DENIED,
        PRIVILEGE_ESCALATION, FILE_ACCESS, CONFIGURATION_CHANGE,
        NETWORK_CONNECTION, SUSPICIOUS_ACTIVITY, SYSTEM_ERROR
    }

    public enum Severity {
        LOW(1), MEDIUM(2), HIGH(3), CRITICAL(4);

        private final int level;
        Severity(int level) { this.level = level; }
        public int getLevel() { return level; }
