            this.timestamp = LocalDateTime.now();
            this.type = type;
            this.severity = severity;
            this.source = source;
            this.userId = userId;
            this.ipAddress = ipAddress;
            this.description = description;
            this.metadata = new HashMap<>();
        }

        public void addMetadata(String key, String value) {
            metadata.put(key, value);
        }

        public String getEventId() { return eventId; }
        public LocalDateTime getTimestamp() { return timestamp; }
        public EventType getType() { return type; }
        public Severity getSeverity() { return severity; }
        public String getSource() { return source; }
        public String getUserId() { return userId; }
        public String getIpAddress() { return ipAddress; }
        public String getDescription() { return description; }
        public Map<String, String> getMetadata() { return Collections.unmodifiableMap(metadata); }

        @Override
        public String toString() {
            return String.format("[%s] %s | %s | %s | User: %s | IP: %s | %s",
                timestamp.format(DateTimeFormatter.ISO_LOCAL_DATE_TIME),
                severity, type, eventId, userId, ipAddress, description);
        }
    }

    public static class SecurityLogger {
        private final String logFilePath;
        private final List<SecurityEvent> eventStore;
        private final boolean consoleOutput;
        private final Object lock = new Object();

        public SecurityLogger(String logFilePath, boolean consoleOutput) {
            this.logFilePath = logFilePath;
            this.consoleOutput = consoleOutput;
            this.eventStore = new CopyOnWriteArrayList<>();
            initializeLogFile();
        }

        private void initializeLogFile() {
            try {
                File file = new File(logFilePath);
                File parent = file.getParentFile();
                if (parent != null && !parent.exists()) {
                    parent.mkdirs();
                }
                if (!file.exists()) {
                    file.createNewFile();
