                                List<SecurityEvent> relatedEvents) {
            SecurityAlert alert = new SecurityAlert(type, description, severity, relatedEvents);
            alerts.add(alert);
            System.err.println("SECURITY ALERT: " + alert);
        }

        private void performSecurityAnalysis() {
            LocalDateTime cutoff = LocalDateTime.now().minusMinutes(lockoutDurationMinutes);

            // Check for stale failed login entries
            lastFailedLogin.entrySet().removeIf(entry -> entry.getValue().isBefore(cutoff));

            // Analyze patterns
            analyzeLoginPatterns();
            analyzeAccessPatterns();
        }

        private void analyzeLoginPatterns() {
            Map<String, Long> loginFailuresByIp = logger.getEvents().stream()
                .filter(e -> e.getType() == EventType.LOGIN_FAILURE)
