                        Severity.MEDIUM,
                        logger.getEventsByUser(user).stream()
                            .filter(e -> e.getType() == EventType.FILE_ACCESS)
                            .collect(Collectors.toList()));
                }
            });
        }

        public List<SecurityAlert> getAlerts() {
            return new ArrayList<>(alerts);
        }

        public List<SecurityAlert> getAlertsBySeverity(Severity minSeverity) {
            return alerts.stream()
                .filter(a -> a.getSeverity().getLevel() >= minSeverity.getLevel())
                .collect(Collectors.toList());
        }

