                return String.format("ALERT [%s] %s: %s (Severity: %s, Events: %d)",
                    timestamp.format(DateTimeFormatter.ISO_LOCAL_DATE_TIME),
                    alertType, description, severity, relatedEvents.size());
            }
        }

        public SecurityMonitor(SecurityLogger logger, int maxFailedAttempts, long lockoutDurationMinutes) {
            this.logger = logger;
            this.maxFailedAttempts = maxFailedAttempts;
            this.lockoutDurationMinutes = lockoutDurationMinutes;
            this.failedLoginAttempts = new ConcurrentHashMap<>();
            this.lastFailedLogin = new ConcurrentHashMap<>();
            this.alerts = new CopyOnWriteArrayList<>();
            this.scheduler = Executors.newScheduledThreadPool(1);
            startMonitoring();
        }

        private void startMonitoring() {
            scheduler.scheduleAtFixedRate(this::performSecurityAnalysis, 0, 1, TimeUnit.MINUTES);
        }

        public void shutdown() {
            scheduler.shutdown();
            try {
                if (!scheduler.awaitTermination(5, TimeUnit.SECONDS)) {
                    scheduler.shutdownNow();
                }
            } catch (InterruptedException e) {
                scheduler.shutdownNow();
                Thread.currentThread().interrupt();
            }
        }

        public void processEvent(SecurityEvent event) {
            logger.logEvent(event);

            switch (event.getType()) {
                case LOGIN_FAILURE:
                    handleFailedLogin(event);
                    break;
                case LOGIN_SUCCESS:
                    handleSuccessfulLogin(event);
                    break;
                case PRIVILEGE_ESCALATION:
                    handlePrivilegeEscalation(event);
                    break;
                case ACCESS_DENIED:
                    handleAccessDenied(event);
                    break;
                case SUSPICIOUS_ACTIVITY:
                    handleSuspiciousActivity(event);
                    break;
                default:
                    break;
            }
        }

        private void handleFailedLogin(SecurityEvent event) {
            String key = event.getUserId() + ":" + event.getIpAddress();
            int attempts = failedLoginAttempts.merge(key, 1, Integer::sum);
            lastFailedLogin.put(key, event.getTimestamp());

            if (attempts >= maxFailedAttempts) {
                createAlert("BRUTE_FORCE_DETECTED",
                    String.format("Multiple failed login attempts (%d) for user %s from IP %s",
                        attempts, event.getUserId(), event.getIpAddress()),
                    Severity.HIGH,
                    logger.getEventsByUser(event.getUserId()).stream()
                        .filter(e -> e.getType() == EventType.LOGIN_FAILURE)
                        .filter(e -> e.getIpAddress().equals(event.getIpAddress()))
                        .collect(Collectors.toList()));
            }
        }

        private void handleSuccessfulLogin(SecurityEvent event) {
            String key = event.getUserId() + ":" + event.getIpAddress();
            failedLoginAttempts.remove(key);
            lastFailedLogin.remove(key);
        }

        private void handlePrivilegeEscalation(SecurityEvent event) {
            createAlert("PRIVILEGE_ESCALATION",
                String.format("Privilege escalation detected for user %s: %s",
                    event.getUserId(), event.getDescription()),
                Severity.CRITICAL,
                Collections.singletonList(event));
        }

        private void handleAccessDenied(SecurityEvent event) {
            List<SecurityEvent> recentDenials = logger.getEventsByUser(event.getUserId()).stream()
                .filter(e -> e.getType() == EventType.ACCESS_DENIED)
                .filter(e -> e.getTimestamp().isAfter(LocalDateTime.now().minusMinutes(5)))
                .collect(Collectors.toList());

            if (recentDenials.size() >= 5) {
                createAlert("REPEATED_ACCESS_DENIED",
                    String.format("User %s has %d access denials in last 5 minutes",
                        event.getUserId(), recentDenials.size()),
                    Severity.MEDIUM,
                    recentDenials);
            }
        }

        private void handleSuspiciousActivity(SecurityEvent event) {
            createAlert("SUSPICIOUS_ACTIVITY",
                String.format("Suspicious activity detected: %s", event.getDescription()),
                Severity.HIGH,
                Collections.singletonList(event));
        }

        private void createAlert(String type, String description, Severity severity,
                                List<SecurityEvent> relatedEvents) {
            SecurityAlert alert = new SecurityAlert(type, description, severity, relatedEvents);
            alerts.add(alert);
            System.err.println("SECURITY ALERT: " + alert);
        }

        private void performSecurityAnalysis() {
            LocalDateTime cutoff = LocalDateTime.now().minusMinutes(lockoutDurationMinutes);

            // Check for stale failed login entries
            lastFailedLogin.entrySet().removeIf(entry -> entry.getValue().isBefore(cutoff));

            // Analyze patterns
            analyzeLoginPatterns();
            analyzeAccessPatterns();
        }

        private void analyzeLoginPatterns() {
            Map<String, Long> loginFailuresByIp = logger.getEvents().stream()
                .filter(e -> e.getType() == EventType.LOGIN_FAILURE)
                .filter(e -> e.getTimestamp().isAfter(LocalDateTime.now().minusHours(1)))
                .collect(Collectors.groupingBy(SecurityEvent::getIpAddress, Collectors.counting()));

            loginFailuresByIp.forEach((ip, count) -> {
                if (count > 10) {
                    createAlert("HIGH_FAILURE_RATE_IP",
                        String.format("IP %s has %d failed login attempts in last hour", ip, count),
                        Severity.HIGH,
                        logger.getEventsByIp(ip).stream()
                            .filter(e -> e.getType() == EventType.LOGIN_FAILURE)
                            .collect(Collectors.toList()));
                }
            });
        }

        private void analyzeAccessPatterns() {
            Map<String, Long> accessByUser = logger.getEvents().stream()
                .filter(e -> e.getType() == EventType.FILE_ACCESS)
                .filter(e -> e.getTimestamp().isAfter(LocalDateTime.now().minusHours(1)))
                .collect(Collectors.groupingBy(SecurityEvent::getUserId, Collectors.counting()));

            accessByUser.forEach((user, count) -> {
                if (count > 100) {
                    createAlert("UNUSUAL_FILE_ACCESS_VOLUME",
                        String.format("User %s accessed %d files in last hour", user, count),
                        Severity.MEDIUM,
                        logger.getEventsByUser(user).stream()
                            .filter(e -> e.getType() == EventType.FILE_ACCESS)
                            .collect(Collectors.toList()));
                }
            });
        }

        public List<SecurityAlert> getAlerts() {
            return new ArrayList<>(alerts);
        }

        public List<SecurityAlert> getAlertsBySeverity(Severity minSeverity) {
            return alerts.stream()
                .filter(a -> a.getSeverity().getLevel() >= minSeverity.getLevel())
                .collect(Collectors.toList());
        }

        public Map<String, Object> generateSecurityReport(LocalDateTime start, LocalDateTime end) {
            List<SecurityEvent> events = logger.getEventsByTimeRange(start, end);
            List<SecurityAlert> periodAlerts = alerts.stream()
                .filter(a -> !a.getTimestamp().isBefore(start) && !a.getTimestamp().isAfter(end))
                .collect(Collectors.toList());

            Map<String, Object> report = new HashMap<>();
            report.put("periodStart", start);
            report.put("periodEnd", end);
            report.put("totalEvents", events.size());
            report.put("totalAlerts", periodAlerts.size());
            report.put("eventsByType", events.stream()
                .collect(Collectors.groupingBy(SecurityEvent::getType, Collectors.counting())));
            report.put("eventsBySeverity", events.stream()
                .collect(Collectors.groupingBy(SecurityEvent::getSeverity, Collectors.counting())));
            report.put("criticalAlerts", periodAlerts.stream()
                .filter(a -> a.getSeverity() == Severity.CRITICAL)
                .collect(Collectors.toList()));
            report.put("topFailedLoginUsers", events.stream()
                .filter(e -> e.getType() == EventType.LOGIN_FAILURE)
                .collect(Collectors.groupingBy(SecurityEvent::getUserId, Collectors.counting()))
                .entrySet().stream()
                .sorted(Map.Entry.<String, Long>comparingByValue().reversed())
                .limit(5)
                .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue)));

            return report;
        }

